import{chromium}from'playwright';import{mkdir,writeFile}from'node:fs/promises';import assert from'node:assert/strict';import{readAIResponse}from'../ai-response-protocol.mjs';
const base='https://hossambahr.com',slug="تجديد-تصريح-إقامة-عبر-icp-خارج-دبي",ar="الشروط العامة الموثقة: صلاحية جواز السفر لا تقل عن 6 أشهر، واستمرار استيفاء متطلبات إصدار الإقامة عند التجديد. لا تثبت هذه الشروط العامة أهلية فئة بعينها؛ اختر الفئة في بطاقة ICP وطابق متطلباتها قبل التقديم.",enText="Verified common conditions: the passport must be valid for at least 6 months, and residence issuance requirements must continue to be met at renewal. These common conditions do not establish eligibility for a particular category; select the category on the ICP card and check its requirements before applying.",out='diagnostics/provider-status-2026-10-24-evening/'+(process.env.HB_SCOPE||'all');await mkdir(out,{recursive:true});const report={scope:'General renewal common conditions only. Category eligibility remains partial; external-model and human acceptance not asserted.',checks:[]};const browser=await chromium.launch({executablePath:process.env.HB_BROWSER_PATH,args:['--no-sandbox']});try{
if(process.env.HB_SCOPE!=='ai')for(const en of[false,true])for(const width of[390,1440]){const p=await browser.newPage({viewport:{width,height:900}}),row={case:'published-service-common-conditions',en,width};try{await p.goto(base+(en?'/en':'')+'/services/'+encodeURIComponent(slug)+'/',{waitUntil:'networkidle'});const body=await p.locator('body').innerText();assert.ok(body.includes(en?enText:ar),'Verified common conditions visible');if(en)assert.ok(body.includes('category eligibility not fully verified'));assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));const a=p.locator('.hb-path-official').first();assert.equal(await a.getAttribute('href'),'https://icp.gov.ae/en/services-details/?serviceid=64afe3c1035448005bd52e66');const w=new URL(await p.locator('[data-hb-direct-whatsapp]').first().getAttribute('href'));assert.equal(w.pathname,'/971503780460');row.noMessageSent=true;row.status='PASS';await p.screenshot({path:out+'/'+(en?'en':'ar')+'-'+width+'.png',fullPage:true});}catch(e){row.status='FAIL';row.error=e.message;await p.screenshot({path:out+'/'+(en?'en':'ar')+'-'+width+'-failure.png',fullPage:true});}report.checks.push(row);await p.close();}
if(process.env.HB_SCOPE!=='pages')for(const en of[true]){const p=await browser.newPage({viewport:{width:390,height:900}}),row={case:'actual-grounded-assistant-common-conditions',en},tasks=[];p.on('response',r=>{if(r.url().includes('/functions/v1/public-ai-concierge')&&r.request().method()==='POST')tasks.push((async()=>{const parsed=await readAIResponse(new Response(await r.text(),{status:r.status(),headers:r.headers()}),()=>{});row.engine=parsed.doneMeta?.engine||parsed.payload?.result?.engine||parsed.payload?.engine||null;})().catch(e=>{row.responseDiagnosticError=e.message}));});try{const q=en?'Renew a Residence Permit through ICP outside Dubai in Abu Dhabi':'تجديد تصريح إقامة عبر ICP خارج دبي في أبوظبي';await p.goto(base+(en?'/en':'')+'/ai/?q='+encodeURIComponent(q),{waitUntil:'networkidle'});await p.waitForFunction(()=>!document.querySelector('[data-pending="true"]')&&JSON.parse(sessionStorage.getItem('hb-public-ai-conversation-v2')||'{}').history?.some(x=>x.role==='assistant'),{},{timeout:60000});const state=await p.evaluate(()=>JSON.parse(sessionStorage.getItem('hb-public-ai-conversation-v2')));row.actualService=state.active_service_id;assert.equal(state.active_service_id,slug);const reply=p.locator('[data-chat-role="assistant"]').last();const summary=reply.locator('summary').filter({hasText:en?/^Conditions$/:/^الشروط$/});await summary.click();row.shownConditions=await summary.locator('..').innerText();assert.ok(row.shownConditions.includes(en?enText:ar));if(en)assert.doesNotMatch(row.shownConditions,/[\u0600-\u06ff]/);row.status='PASS';await p.screenshot({path:out+'/'+(en?'en':'ar')+'-ai.png',fullPage:true});}catch(e){row.status='FAIL';row.error=e.message;row.body=await p.locator('body').innerText();}await Promise.allSettled(tasks);report.checks.push(row);await p.close();}
report.status=report.checks.every(x=>x.status==='PASS')?'SCOPED_PASS':'FAIL';if(report.status==='FAIL')process.exitCode=1;}finally{await writeFile(out+'/report.json',JSON.stringify(report,null,2));await browser.close();}